using System;using System.IO;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using Mewgic;using Mewgic.Daily;
public static class DailyHomeEntryTests
{
 static readonly List<string> checks=new List<string>();static void Check(bool ok,string n){if(!ok)throw new Exception(n);checks.Add(n);}
 static Rect Bounds(RectTransform r,RectTransform safe,bool padded=false){var local=r.rect;if(padded){var p=r.GetComponent<Image>().raycastPadding;local=Rect.MinMaxRect(local.xMin+p.x,local.yMin+p.y,local.xMax-p.z,local.yMax-p.w);}var a=(Vector2)safe.InverseTransformPoint(r.TransformPoint(local.min));var b=(Vector2)safe.InverseTransformPoint(r.TransformPoint(local.max));return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
 public static void Run()
 {
  var ui=UnityEngine.Object.FindFirstObjectByType<DailyActivitiesPanel>();if(ui==null||!EditorApplication.isPlaying)throw new Exception("Home Play Mode required");ui.Close();checks.Clear();
  foreach(var shape in new[]{new Vector2Int(900,1600),new Vector2Int(900,1950),new Vector2Int(900,2000),new Vector2Int(360,640)}){
   var entry=GameObject.Find("DailyGiftButton");var safe=(RectTransform)entry.transform.parent.parent;var canvas=safe.GetComponentInParent<Canvas>();var camera=Camera.main;var target=camera.targetTexture;var old=RenderTexture.active;var mode=canvas.renderMode;var cam=canvas.worldCamera;var plane=canvas.planeDistance;var rt=new RenderTexture(shape.x,shape.y,24);Texture2D tex=null;
   try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;camera.targetTexture=rt;Canvas.ForceUpdateCanvases();UnityEngine.Object.FindFirstObjectByType<HomeCharacterPresenter>().Layout();ui.Layout();Canvas.ForceUpdateCanvases();var first=Bounds((RectTransform)entry.transform,safe,true);var second=Bounds((RectTransform)GameObject.Find("MissionsButton").transform,safe,true);Check(!first.Overlaps(second),"Home daily hit targets do not overlap "+shape);
    foreach(var name in new[]{"DailyGiftButton","MissionsButton"}){var r=(RectTransform)GameObject.Find(name).transform;var bounds=Bounds(r,safe,true);Check(safe.rect.Contains(bounds.min)&&safe.rect.Contains(bounds.max),"Daily entry within safe area "+name+shape);Check(bounds.width*canvas.scaleFactor>=43.9f&&bounds.height*canvas.scaleFactor>=43.9f,"Home minimum44px hit area "+name+shape);foreach(var other in new[]{"Play","MewgicLogo","HomeBottomNavigation","Subtitle"})Check(!bounds.Overlaps(Bounds((RectTransform)GameObject.Find(other).transform,safe)),"Daily entry avoids "+other+shape);Check(!bounds.Overlaps(Bounds(UnityEngine.Object.FindFirstObjectByType<HomeCharacterPresenter>().character,safe)),"Daily entry avoids cat "+shape);}
    camera.Render();RenderTexture.active=rt;tex=new Texture2D(shape.x,shape.y,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,shape.x,shape.y),0,0);tex.Apply();File.WriteAllBytes("docs/PART07A_HOME_LAYOUT_"+shape.x+"x"+shape.y+".png",tex.EncodeToPNG());
   }finally{camera.targetTexture=target;RenderTexture.active=old;canvas.renderMode=mode;canvas.worldCamera=cam;canvas.planeDistance=plane;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();UnityEngine.Object.FindFirstObjectByType<HomeCharacterPresenter>().Layout();ui.Layout();}
  }
  foreach(var name in new[]{"DailyGiftButton","MissionsButton"}){var g=GameObject.Find(name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Home top raycast "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);Check(ui.IsOpen&&ui.GiftVisible==(name=="DailyGiftButton"),"Home entry opens correct tab "+name);ui.Close();}
  File.WriteAllText("docs/PART07A_HOME_TEST_RESULTS.json",JsonUtility.ToJson(new Result{success=true,count=checks.Count,checks=checks.ToArray()},true));
 }
 [Serializable]class Result{public bool success;public int count;public string[] checks;}
}
